export function mathQuestions({operation='add',limit=10,count=20,seed='practice-1'}={}){
 if(!['add','subtract','multiply','mixed'].includes(operation)||![10,20,100].includes(+limit)||![12,20,30].includes(+count))throw Error('Choose a supported arithmetic set.');
 let state=2166136261;for(const c of String(seed))state=Math.imul(state^c.codePointAt(0),16777619)>>>0;const random=()=>((state=(Math.imul(state,1664525)+1013904223)>>>0)/4294967296),int=n=>Math.floor(random()*(n+1)),items=[],seen=new Set();
 for(let tries=0;items.length<+count&&tries<10000;tries++){const op=operation==='mixed'?['add','subtract','multiply'][int(2)]:operation;let a=int(op==='multiply'?12:+limit),b=int(op==='multiply'?12:+limit);if(op==='subtract'&&a<b)[a,b]=[b,a];const sign={add:'+',subtract:'−',multiply:'×'}[op],question=a+' '+sign+' '+b;if(seen.has(question))continue;seen.add(question);items.push({a,b,operation:op,question,answer:op==='add'?a+b:op==='subtract'?a-b:a*b});}
 if(items.length!==+count)throw Error('Could not create enough unique questions. Choose another set.');return items;
}
const paperSize=paper=>paper==='letter'?{width:816,height:1056}:{width:794,height:1123};
function documentSVG(title,subtitle,body,{paper='a4',name=''}={}){const {width:W,height:H}=paperSize(paper);return `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}" role="img" aria-label="${e(title)} worksheet"><title>${e(title)} worksheet</title><rect width="100%" height="100%" fill="white"/><g fill="#202623" font-family="Arial,sans-serif"><text x="40" y="51" font-size="28" font-weight="700">${e(title)}</text><text x="40" y="79" font-size="13">${e(subtitle)}</text><text x="40" y="113" font-size="13">Name: ${e(Array.from(name).slice(0,35).join(''))}${name?'':'_________________________________'}</text><text x="${W-225}" y="113" font-size="13">Date: __________________</text><path d="M40 132H${W-40}" stroke="#69716c" stroke-width="1.2"/>${body}<path d="M40 ${H-47}H${W-40}" stroke="#c1c6c2"/><text x="40" y="${H-27}" font-size="10" fill="#69716c">NEPOCORE · A LITTLE PRACTICE, EVERY DAY</text><text x="${W-40}" y="${H-27}" text-anchor="end" font-size="10" fill="#69716c">Free printable worksheet</text></g></svg>`;}
function guides(y,W){return `<path d="M48 ${y}H${W-48}M48 ${y+57}H${W-48}" stroke="#9ca39e" stroke-width="1"/><path d="M48 ${y+29}H${W-48}" stroke="#c0c5c1" stroke-width="1" stroke-dasharray="6 5"/>`;}
