export function worksheetPages(options={}){
 const type=options.type||'alphabet',paper=options.paper==='letter'?'letter':'a4',{width:W,height:H}=paperSize(paper),opts={paper,name:options.name||''};let body='',title='',subtitle='',key=null,questions=[];
 if(type==='math'){
  questions=mathQuestions({operation:options.operation||'add',limit:+options.limit||10,count:+options.count||20,seed:options.seed||'practice-1'});title={add:'Addition practice',subtract:'Subtraction practice',multiply:'Multiplication practice',mixed:'A little mixed math'}[options.operation||'add'];subtitle='Solve each problem. Take your time and show your thinking.';
  const columns=questions.length===30?3:2,rows=Math.ceil(questions.length/columns),cw=(W-80)/columns,rh=(H-220)/rows;
  function questionGrid(answers){return questions.map((q,i)=>{const x=48+i%columns*cw,y=177+Math.floor(i/columns)*rh;return `<text x="${x}" y="${y}" font-size="11" fill="#747b76">${i+1}.</text><text x="${x+24}" y="${y+28}" font-size="${columns===3?20:25}">${e(q.question)} = ${answers?q.answer:'____'}</text>${answers?'':`<path d="M${x+24} ${y+rh-12}H${x+cw-21}" stroke="#d4d7d5" stroke-dasharray="3 5"/>`}`;}).join('');}
  body=questionGrid(false);if(options.key==='yes')key=documentSVG(title+' · answers','Answer key · '+questions.length+' questions · set '+String(options.seed||'practice-1').slice(0,24),questionGrid(true),opts);
 }else if(type==='alphabet'){
  const focus=options.alphabetMode==='focus',letter=String(options.letter??'A').toUpperCase();if(!/^[A-Z]$/.test(letter))throw Error('Choose one English letter from A to Z.');
  title=focus?letter+' is for '+words[alphabet.indexOf(letter)]:'My alphabet practice';subtitle=focus?'Say the letter. Trace it. Write it. Find it.':'Say each letter, trace the pale letters, then write your own.';
  if(focus){body=`<text x="${W/2}" y="269" text-anchor="middle" font-size="150" fill="none" stroke="#444" stroke-width="1.5">${letter+letter.toLowerCase()}</text>`;for(let i=0;i<3;i++){const y=313+i*98;body+=guides(y,W)+`<text x="58" y="${y+51}" font-size="47" fill="#b0b5b1" textLength="${W-116}" lengthAdjust="spacingAndGlyphs">${(letter+' '+letter.toLowerCase()+' ').repeat(5).trim()}</text>`;}body+=`<text x="48" y="659" font-size="19" font-weight="700">Circle every ${letter} and ${letter.toLowerCase()} you can find.</text>`;for(let r=0;r<4;r++)for(let c=0;c<8;c++){const i=r*8+c,v=i%5===0?letter:alphabet[(i*7+alphabet.indexOf(letter)+3)%26];body+=`<text x="${67+c*(W-115)/8}" y="${716+r*65}" font-size="33">${i%2?v.toLowerCase():v}</text>`;}}
  else{const cw=(W-80)/4,rh=(H-214)/7;for(const [i,letter]of Array.from(alphabet).entries()){const x=40+i%4*cw,y=153+Math.floor(i/4)*rh;body+=`<rect x="${x}" y="${y}" width="${cw-7}" height="${rh-9}" rx="7" fill="none" stroke="#b7bdb8"/><text x="${x+12}" y="${y+37}" font-size="32" font-weight="700">${letter+letter.toLowerCase()}</text><text x="${x+12}" y="${y+59}" font-size="13">${words[i]}</text><text x="${x+12}" y="${y+90}" font-size="26" fill="#b0b5b1">${letter+' '+letter.toLowerCase()}</text><path d="M${x+69} ${y+94}H${x+cw-19}" stroke="#adb4ae"/>`;}}
 }else if(type==='handwriting'){
  const text=String(options.practice??'My name is a little story.').trim();if(!text||Array.from(text).length>80)throw Error('Use 1–80 characters for handwriting practice.');title='My handwriting practice';subtitle='Trace the pale words. Then write your own on the last two lines.';const lines=[];let line='';for(const word of text.split(/\s+/)){if((line+' '+word).trim().length>37&&line){lines.push(line);line=word;}else line+=(line?' ':'')+word;}if(line)lines.push(line);for(let i=0;i<8;i++){const y=154+i*(H-223)/8;body+=guides(y,W);if(i<6){const value=lines[i%lines.length];body+=`<text x="57" y="${y+49}" font-size="34" fill="#b0b5b1" textLength="${Math.min(W-113,Math.max(21,Array.from(value).length*18))}" lengthAdjust="spacingAndGlyphs">${e(value)}</text>`;}}
 }else if(type==='coloring'){
  const theme=options.theme||'cat';title='Color a little '+theme;subtitle='Choose your colors. Add a background. Make this picture your own.';const size=Math.min(W-90,H-242),x=(W-size)/2,y=167+(H-242-size)/2;body=`<g transform="translate(${x} ${y}) scale(${size/600})">${coloringArt(theme)}</g>`;
 }else throw Error('Choose a worksheet type.');
 const first=documentSVG(title,subtitle,body,opts);return {pages:key?[first,key]:[first],width:W,height:H,type,questions};
}
